import {mapGetters} from 'vuex'
import {securityId, securityAdd, securityEdit, categoryTree} from "@/api/safeDanger/hiddenCategory"

export default {
  name: "ComputerRoomDetail",
  computed: {
    ...mapGetters([
      'nickName',
      'companyId',
      'companyCode',
    ]),
  },
  props: {
    roomId: {
      default: false
    },
    isEdit: {
      type: Boolean,
      default: false
    },
    isInfo: {
      type: Boolean,
      default: false
    }
  },
  data() {
    return {
      // 表单参数
      form: {
        category: undefined,
        content: undefined,
        supervision: undefined,
        supervisionPoint: undefined
      },
      queryDisabled: {
        isSupervision: false,
        isContent: false
      },

      options: [],
      //校验
      rules: {
        category: [{required: true, message: '请填写或选择分类', trigger: 'change'}],
        name: [{required: true, message: '请输入分类名称', trigger: 'blur'}],
      },

      parentDis: false
    }
  },
  created() {
    this.initData()
    this.showInfo();
  },
  mounted() {

  },
  methods: {
    initData() {
      categoryTree({
        pageNum: 1,
        pageSize: 50
      }).then(response => {
        // let arr = []
        // let datas = response.data
        // console.log(77777777)
        // function xunhuan(datas){
        //   datas.forEach(el=>{
        //     arr.push({
        //       id: el.id,
        //       name: el.name,
        //     })
        //     if(el.hiddenCategoryVOList){
        //       xunhuan(el.hiddenCategoryVOList)
        //     }
        //   })
        // }
        // xunhuan(datas)

        // response.data.forEach(ele => {
        //   ele.id = Number(ele.id)
        // });
        this.options = response.data
      })
    },
    showInfo() {
      // this.resetForm("form");
      if (this.roomId) {
        securityId(this.roomId).then(response => {
          let datas = Object.assign({}, response.data)
          // datas.parentId = datas.parentId.toString()
          if (datas.parentId === '0') {
            datas.parentId = undefined
          }
          this.form = datas
        })
      }
    },
    /** 提交按钮 */
    submitForm: function () {

      this.$refs["form"].validate(valid => {
        if (valid) {
          if (this.roomId) {
            // if(!this.form.parentId){
            //   this.form.parentId = undefined
            // }
            securityEdit(this.form).then(response => {
              if (response.code === 200) {
                this.msgSuccess("修改成功");
                this.$emit('closeRoom')
              } else {
                this.msgError(response.msg);
              }
            });
          } else {
            securityAdd(this.form).then(response => {
              if (response.code === 200) {
                this.msgSuccess("新增成功");
                this.$emit('closeRoom')
              } else {
                this.msgError(response.msg);
              }
            });
          }
        }
      });
    },
  }
}
